import{_ as o,l as r,o as e,c as n,v as l,p as s,x as t,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"并行思考与聚合","description":"","frontmatter":{"title":"并行思考与聚合","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/parallel-thinking.md","filePath":"llm/parallel-thinking.md","lastUpdated":1789023840000}'),c={name:"llm/parallel-thinking.md"};function A(E,a,N,m,_,f){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="并行思考与聚合" tabindex="-1">并行思考与聚合 <a class="header-anchor" href="#并行思考与聚合" aria-label="Permalink to &quot;并行思考与聚合&quot;">​</a></h1><div class="epigraph"><p>同一题采多条链再投票或再验证，用宽度换串行深度；聚合规则决定是多数票还是最强验证器。</p><footer>—— Wang 等 Self-Consistency；Best-of-N + PRM；o1/o3 类系统的测试时采样</footer></div><p><a href="/llm/self-verification-backtrack">上一课</a>用一条链上的回溯做串行搜索。缺口是：<strong>一条链陷在错误前缀里，回溯也出不来；独立重采样可以换前缀。</strong> Self-consistency 对算术题多数票；推理模型把 \\(N\\) 加大，用 PRM 或校验器选。本课写并行思考，对照 <a href="/llm/thinking-budget-adaptive">思考预算</a> 的串行 FLOPs。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>测试时计算两条轴：加长一条链；\\(N\\) 条短链再聚合。Snell 等讨论过最优分配。可验证域聚合简单：任一对则对，或多数票。开放域多数票会强化共同偏见。PRM / RM 选 Best-of-N 会过优化验证器（Gao 曲线的 BoN 版）。</p><p>训练与推理的 \\(N\\) 不要混：<a href="/llm/grpo">GRPO</a> 的 \\(G\\) 只在训练；服务上的并行是另一笔钱。用户 SLA 往往只能 \\(N=1\\)，并行留给离线或贵档位。</p><h3 id="聚合器是第二套策略" tabindex="-1">聚合器是第二套策略 <a class="header-anchor" href="#聚合器是第二套策略" aria-label="Permalink to &quot;聚合器是第二套策略&quot;">​</a></h3><p>投票、最长思维、最高 RM、校验器、再由模型总结 \\(N\\) 条，结果不同。总结器会引入新幻觉。有校验器时禁止总结器改答案。</p><p><span class="marginnote">相关采样（同种子、低温度）让 \\(N\\) 条几乎相同，并行费钱无增益。要温度与独立 RNG。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：\\(\\tau\\)、\\(N\\)、是否工具、聚合函数。可验证：先过校验器的子集，再在对的里面选最短（长度控制）。无校验器：self-consistency 或 PRM。训练：一般不把服务 \\(N\\) 写进 GRPO；可用 BoN 蒸馏把并行行为教给 \\(N=1\\) 学生（后课蒸馏）。</p>',11)),(e(),s(h,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%A2%98%E7%9B%AE%22%5D%20--%3E%20N%5B%22%E7%8B%AC%E7%AB%8B%E9%87%87%E6%A0%B7%20N%20%E6%9D%A1%E9%93%BE%22%5D%0A%20%20N%20--%3E%20AGG%7B%22%E8%81%9A%E5%90%88%22%7D%0A%20%20AGG%20--%3E%20VOTE%5B%22%E5%A4%9A%E6%95%B0%E7%A5%A8%22%5D%0A%20%20AGG%20--%3E%20VER%5B%22%E6%A0%A1%E9%AA%8C%E5%99%A8%20%2F%20PRM%20%E9%80%89%22%5D%0A%20%20AGG%20--%3E%20SHORT%5B%22%E5%AF%B9%E7%9A%84%E9%87%8C%E9%9D%A2%E9%80%89%E7%9F%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>与混合模式：简单题 \\(N=1\\) 短模式；难题才并行。路由错误同样贵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立样本近似对解空间做蒙特卡洛。错误前缀不共享时，覆盖优于单链回溯。样本不独立（都抄同一错误模板）时，多数票更错。多样性来自温度、提示扰动、工具。熵塌的模型并行也没用。</p><p><span class="marginnote">并行 + 超长预算是费用平方。帕累托上应先加更有效的那一轴。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>产品默认 \\(N=1\\)。评测 avg@32 不是用户体验。墙钟上 \\(N\\) 条并行仍受 KV 与批调度限制，标称 \\(N\\) 倍算力不等于 \\(N\\) 倍延迟。下一课蒸馏：把高 \\(N\\) 或长链教师压进小模型单样本。aha 与语言混杂仍是单链现象，并行只是外层。</p><p>服务 N 与训练 G 不是同一个数。低多样时并行浪费；有校验器时禁止总结器改写已经核对过的答案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并行思考用 \\(N\\) 条独立链换覆盖；聚合规则必须声明。</li><li>可验证域用校验器再选短；开放域 BoN 会过优化 RM/PRM。</li><li>训练 \\(G\\) ≠ 服务 \\(N\\)。</li><li>低多样时并行浪费；先保证熵与温度。</li><li>出处：Wang 等 Self-Consistency；Lightman PRM BoN；Snell 测试时计算；Gao BoN 过优化。</li></ul>',9))])}const P=o(c,[["render",A]]);export{B as __pageData,P as default};
